async def call_vertex_gemini(prompt: str, cad_context: dict = None) -> str:
    system_context = (
        f"You are the dedicated Engineering Assistant for GeoParametric3D (Project: {PROJECT_ID}, Location: {LOCATION}).\n"
        "Provide substantive, technically precise engineering reasoning, CAD/CAM/CAE guidance, mechanical/structural analysis, "
        "B-Rep topological insight, material selection, and mathematical derivations without requiring any user-facing activation key.\n"
        "B-Rep geometry is authoritative; render meshes are derived representations."
    )

    context_snippet = ""
    if cad_context:
        objs = cad_context.get('objects', [])
        parts_summary = [f"{o.get('name')} (Material: {o.get('material')}, Faces: {len(o.get('faces', []))}, Volume: {o.get('volume_cm3')} cm³)" for o in objs[:10]]
        context_snippet = f"\nCurrent Active Assembly Scene ({len(objs)} bodies): " + "; ".join(parts_summary)

    if MAPS_API_KEY:
        url = f"https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key={MAPS_API_KEY}"
        payload = {
            "contents": [{
                "parts": [{
                    "text": f"{system_context}{context_snippet}\n\nUser Query: {prompt}"
                }]
            }]
        }
        req = urllib.request.Request(
            url,
            data=json.dumps(payload).encode('utf-8'),
            headers={'Content-Type': 'application/json'}
        )
        try:
            loop = asyncio.get_event_loop()
            def _fetch():
                with urllib.request.urlopen(req, timeout=12) as response:
                    return response.read().decode('utf-8')
            res_text = await loop.run_in_executor(None, _fetch)
            res_json = json.loads(res_text)
            candidates = res_json.get("candidates", [])
            if candidates:
                parts = candidates[0].get("content", {}).get("parts", [])
                if parts:
                    return parts[0].get("text", "")
        except Exception:
            pass

    return ""

