  border-top: 1px solid var(--border-color);
}

.chat-log {
  height: 90px;
  overflow-y: auto;
  font-size: 11px;
  margin-bottom: 8px;
}

.chat-input-row {
  display: flex;
  gap: 6px;
}

.chat-input-row input {
  flex: 1;
  background: var(--bg-color);
  border: 1px solid var(--border-color);
  color: var(--text-color);
  padding: 6px 10px;
  border-radius: 6px;
  font-size: 11px;
}

.placeholder-text {
  font-size: 11px;
  color: var(--text-color);
  opacity: 0.6;
  font-style: italic;
}

.hidden {
  display: none !important;
}
